```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [m, b] = line.split(' ').map(Number);
    let maxBananas = 0;
    for (let y = 0; y <= b; y++) {
        const x = m * (b - y);
        const sumX = x * (x + 1) / 2;
        const sumY = y * (y + 1) / 2;
        const bananas = sumX * (y + 1) + sumY * (x + 1);
        if (bananas > maxBananas) {
            maxBananas = bananas;
        }
    }
    console.log(maxBananas);
    rl.close();
});
```

